import java.util.*;

public class Main {
    // Supprime de la liste toutes les fiches de cote négative.
    static void retirerPerimees(List<Integer> fiches) {
        for (Integer f : fiches) {
            if (f < 0) {
                fiches.remove(f);
            }
        }
    }

    // Supprime UNE fiche portant la cote donnée (la première trouvée) ; ne fait rien si elle est absente.
    static void retirerCote(List<Integer> fiches, int cote) {
        fiches.remove(cote);
    }
}
